export type EventCallback<T = any> = (payload: T) => void;

export class EventBus {
  private subscribers: Map<string, Set<EventCallback>> = new Map();

  publish<T = any>(event: string, payload: T): void {
    const subs = this.subscribers.get(event);
    if (!subs || subs.size === 0) return;
    // Deliver asynchronously to avoid blocking publishers
    for (const cb of subs) {
      try {
        // Use setImmediate to schedule callbacks
        setImmediate(() => {
          try {
            cb(payload);
          } catch (err) {
            // Swallow errors from subscribers to avoid affecting others
            console.error(`Error in subscriber for event ${event}:`, err);
          }
        });
      } catch (err) {
        console.error(`Error scheduling subscriber for event ${event}:`, err);
      }
    }
  }

  subscribe<T = any>(event: string, callback: EventCallback<T>): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, new Set());
    }
    this.subscribers.get(event)!.add(callback as EventCallback);
  }
}

import { randomUUID } from 'crypto';

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();

  create(input: { name: string; email: string }): User {
    const id = randomUUID();
    const user: User = { id, name: input.name, email: input.email };
    this.users.set(id, user);
    return user;
  }

  getById(id: string): User | undefined {
    return this.users.get(id);
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, patch: Partial<Omit<User, 'id'>>): User | undefined {
    const existing = this.users.get(id);
    if (!existing) return undefined;
    const updated: User = { ...existing, ...patch, id };
    this.users.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.users.delete(id);
  }
}

import { randomUUID } from 'crypto';

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();

  create(input: { name: string; description: string }): Project {
    const id = randomUUID();
    const project: Project = {
      id,
      name: input.name,
      description: input.description,
      memberIds: [],
    };
    this.projects.set(id, project);
    return project;
  }

  getById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, patch: Partial<Omit<Project, 'id' | 'memberIds'>>): Project | undefined {
    const existing = this.projects.get(id);
    if (!existing) return undefined;
    const updated: Project = { ...existing, ...patch, id };
    this.projects.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project | undefined {
    const project = this.projects.get(projectId);
    if (!project) return undefined;
    project.memberIds = project.memberIds.filter((id) => id !== userId);
    return project;
  }
}

import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  constructor(private eventBus: EventBus) {}

  create(input: { title: string; description: string; projectId: string; assigneeId?: string | null }): Task {
    const id = randomUUID();
    const task: Task = {
      id,
      title: input.title,
      description: input.description,
      status: 'todo',
      assigneeId: input.assigneeId ?? null,
      projectId: input.projectId,
    };
    this.tasks.set(id, task);
    if (task.assigneeId) {
      this.eventBus.publish('task.assigned', {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: task.assigneeId,
      });
    }
    return task;
  }

  getById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter((t) => t.projectId === projectId);
  }

  update(id: string, patch: Partial<Omit<Task, 'id' | 'status' | 'assigneeId'>>): Task | undefined {
    const existing = this.tasks.get(id);
    if (!existing) return undefined;
    const updated: Task = { ...existing, ...patch, id };
    this.tasks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.tasks.delete(id);
  }

  assign(id: string, assigneeId: string | null): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;
    task.assigneeId = assigneeId;
    this.eventBus.publish('task.assigned', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
    });
    return task;
  }

  changeStatus(id: string, newStatus: TaskStatus): Task | undefined {
    const task = this.tasks.get(id);
    if (!task) return undefined;

    const order: TaskStatus[] = ['todo', 'in-progress', 'done'];
    const currentIndex = order.indexOf(task.status);
    const newIndex = order.indexOf(newStatus);
    if (newIndex === -1) return undefined;
    if (newIndex < currentIndex) {
      throw new Error('Backward status transitions are not allowed');
    }
    if (newIndex === currentIndex) return task; // no-op

    const oldStatus = task.status;
    task.status = newStatus;
    this.eventBus.publish('task.statusChanged', {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus,
      newStatus,
    });
    return task;
  }
}

