import { randomUUID } from 'crypto';
import { EventBus } from '../event-bus';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();

  constructor(eventBus: EventBus) {
    // Subscribe to events
    eventBus.subscribe('task.assigned', (payload: { taskId: string; taskTitle: string; assigneeId: string | null }) => {
      if (!payload.assigneeId) return; // no target
      const message = `You were assigned to task "${payload.taskTitle}"`;
      this.createNotification(payload.assigneeId, message);
    });

    eventBus.subscribe(
      'task.statusChanged',
      (payload: { taskId: string; taskTitle: string; assigneeId: string | null; oldStatus: string; newStatus: string }) => {
        if (!payload.assigneeId) return;
        const message = `Task "${payload.taskTitle}" status changed: ${payload.oldStatus} -> ${payload.newStatus}`;
        this.createNotification(payload.assigneeId, message);
      }
    );

    eventBus.subscribe(
      'comment.added',
      (payload: { commentId: string; taskId: string; taskTitle: string; authorId: string; authorName: string }) => {
        // In a real system we might need the assignee; here we cannot call TaskService directly,
        // so we rely on the router to include taskTitle and on the idea that the assignee will be notified by other means.
        // But per spec: should create notification for task assignee. Since we don't know assignee here,
        // We'll publish notification to all users is not allowed. Alternative: The router will pass taskTitle and assigneeId via event payload.
        // Update: Adjust contract to allow assigneeId provided if available. If missing, skip.
        const anyPayload: any = payload as any;
        const assigneeId: string | undefined = anyPayload.assigneeId;
        if (!assigneeId) return; // cannot notify without target
        const message = `${payload.authorName || 'Someone'} commented on task "${payload.taskTitle}"`;
        this.createNotification(assigneeId, message);
      }
    );
  }

  private createNotification(userId: string, message: string) {
    const id = randomUUID();
    const createdAt = new Date().toISOString();
    const notif: Notification = { id, userId, message, read: false, createdAt };
    this.notifications.set(id, notif);
  }

  getByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values()).filter((n) => n.userId === userId);
  }

  markAsRead(id: string): Notification | undefined {
    const n = this.notifications.get(id);
    if (!n) return undefined;
    n.read = true;
    return n;
  }
}

// Simple RFC4122 v4-like ID generator without external deps.
export function generateId(): string {
  // Credit: adapted from common snippet
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

